String head(const char* title){String h=legacyHead(title);if(!isJapanese())h.replace("<html lang='ja'>","<html lang='en'>");return h;}
String row(const String& prefix,const char* event,uint8_t i,const OscMessageSetting& m){String p=prefix+(String(event)=="press"?"p":"r");String h="<div class='osc-row' data-event='"+String(event)+"'><div class='order'><button type='button' onclick='moveMsg(this,-1)'>&uarr;</button><button type='button' onclick='moveMsg(this,1)'>&darr;</button></div><label>"+String(tr("OSC Address","OSCアドレス"))+"<input class='addr counted' maxlength='192' required name='"+p+"_address_"+i+"' value='"+esc(m.address)+"' oninput='countBytes(this,192)'><small>"+String(m.address.length())+" / 192 bytes</small></label><label>"+tr("Type","型")+types(p+"_type_"+i,m.type)+"</label><label>"+tr("Value","値")+"<input class='counted' maxlength='128' name='"+p+"_value_"+i+"' value='"+esc(m.value)+"' oninput='countBytes(this,128)'><small>"+String(m.value.length())+" / 128 bytes</small></label><button type='button' class='del' onclick='removeMsg(this)'>"+tr("Delete","削除")+"</button></div>";return h;}
String buttonEditor(const String& g,const String& prefix,const ButtonInputSetting& b,const char* modeLabel,const char* seqTitle){const bool full=b.pressMessageCount+b.releaseMessageCount>=8;String h="<div class='mode'><label>"+String(modeLabel)+"<select name='"+prefix+"mode' onchange=\"toggleMode(this,'"+g+"')\"><option value='0'"+(b.mode==INPUT_MODE_PRESS_RELEASE?" selected":"")+">"+tr("Press / Release","押した時／離した時")+"</option><option value='1'"+(b.mode==INPUT_MODE_SEQUENCE?" selected":"")+">"+tr("Sequence","シーケンス")+"</option></select></label></div>";h+="<div id='pr-"+g+"' class='pr' data-prefix='"+prefix+"' style='display:"+String(b.mode==INPUT_MODE_SEQUENCE?"none":"block")+"'><div class='usage'><b>"+tr("Messages ","メッセージ ")+"<span class='total'>"+String(b.pressMessageCount+b.releaseMessageCount)+"</span> / 8</b><span>"+tr("Press + Release","押した時＋離した時")+"</span></div><input class='pc' type='hidden' name='"+prefix+"p_count' value='"+String(b.pressMessageCount)+"'><input class='rc' type='hidden' name='"+prefix+"r_count' value='"+String(b.releaseMessageCount)+"'><div class='tabs'><button type='button' class='active' onclick=\"showEvent(this,'press')\">"+tr("Press","押した時")+"</button><button type='button' onclick=\"showEvent(this,'release')\">"+tr("Release","離した時")+"</button></div><div class='panel press'><div class='list'>";for(uint8_t i=0;i<b.pressMessageCount;++i)h+=row(prefix,"press",i,b.pressMessages[i]);h+="</div><button type='button' class='add' onclick=\"addMsg(this,'press')\""+String(full?" disabled":"")+">+ "+tr("Add OSC Message","OSCメッセージを追加")+"</button></div><div class='panel release' style='display:none'><div class='list'>";for(uint8_t i=0;i<b.releaseMessageCount;++i)h+=row(prefix,"release",i,b.releaseMessages[i]);h+="</div><button type='button' class='add' onclick=\"addMsg(this,'release')\""+String(full?" disabled":"")+">+ "+tr("Add OSC Message","OSCメッセージを追加")+"</button></div></div>";h+="<div id='seq-"+g+"' class='sequence' style='display:"+String(b.mode==INPUT_MODE_SEQUENCE?"block":"none")+"'><h3>"+seqTitle+"</h3><p>"+tr("Advance by Step from Start to End, then return to Start.","開始値から増減量ずつ進み、終了値を超えると開始値へ戻ります。")+"</p><div class='seqgrid'><label>"+tr("OSC Address","OSCアドレス")+"<input maxlength='192' required name='"+prefix+"seq_address' value='"+esc(b.sequence.address)+"'></label><label>"+tr("Start","開始値")+"<input type='number' step='any' required name='"+prefix+"seq_start' value='"+String(b.sequence.start,7)+"'></label><label>"+tr("End","終了値")+"<input type='number' step='any' required name='"+prefix+"seq_end' value='"+String(b.sequence.end,7)+"'></label><label>"+tr("Step","増減量")+"<input type='number' step='any' required name='"+prefix+"seq_step' value='"+String(b.sequence.step,7)+"'></label><label>"+tr("Type","型")+types(prefix+"seq_type",b.sequence.type)+"</label></div></div>";return h;}

bool parseType(const String& s,OscValueType& t,bool strings=true){if(s.length()!=1||s[0]<'0'||s[0]>(strings?'2':'1'))return false;t=(OscValueType)(s[0]-'0');return true;}
bool parseMessage(const String& prefix,const char* event,uint8_t i,OscMessageSetting& m){String p=prefix+event;m.address=server.arg(p+"_address_"+i);m.address.trim();m.value=server.arg(p+"_value_"+i);return parseType(server.arg(p+"_type_"+i),m.type)&&inputOscMessageValid(m);}
bool parseButton(const String& prefix,ButtonInputSetting& b){b.mode=server.arg(prefix+"mode")=="1"?INPUT_MODE_SEQUENCE:INPUT_MODE_PRESS_RELEASE;int pc=server.arg(prefix+"p_count").toInt(),rc=server.arg(prefix+"r_count").toInt();if(pc<0||rc<0||pc+rc>8)return false;b.pressMessageCount=pc;b.releaseMessageCount=rc;bool ok=true;for(uint8_t i=0;i<b.pressMessageCount;++i)ok=parseMessage(prefix,"p",i,b.pressMessages[i])&&ok;for(uint8_t i=0;i<b.releaseMessageCount;++i)ok=parseMessage(prefix,"r",i,b.releaseMessages[i])&&ok;b.sequence.address=server.arg(prefix+"seq_address");b.sequence.address.trim();ok=parseType(server.arg(prefix+"seq_type"),b.sequence.type)&&ok;ok=inputParseFloat(server.arg(prefix+"seq_start"),b.sequence.start)&&ok;ok=inputParseFloat(server.arg(prefix+"seq_end"),b.sequence.end)&&ok;ok=inputParseFloat(server.arg(prefix+"seq_step"),b.sequence.step)&&ok;inputNormalizeSequence(b.sequence);return ok&&inputButtonSettingValid(b);}
bool parseKey(uint8_t index,KeyInputSetting& s){String prefix="k"+String(index)+"_";s=inputKeySetting(index);s.displayName=server.arg(prefix+"display_name");s.displayName.trim();return !s.displayName.isEmpty()&&s.displayName.length()<=64&&parseButton(prefix,s.button);}
bool parseEncoder(EncoderInputSetting& e){const String prefix="enc_";e=inputEncoderSetting();e.displayName=server.arg(prefix+"display_name");e.displayName.trim();e.rotationAddress=server.arg(prefix+"erot");e.rotationAddress.trim();e.sendIncrement=server.arg(prefix+"emode")=="1";return !e.displayName.isEmpty()&&e.displayName.length()<=64&&parseType(server.arg(prefix+"eotype"),e.outputType)&&inputParseFloat(server.arg(prefix+"eamin"),e.absoluteInputMin)&&inputParseFloat(server.arg(prefix+"eamax"),e.absoluteInputMax)&&inputParseFloat(server.arg(prefix+"escale"),e.incrementScale)&&inputParseFloat(server.arg(prefix+"eomin"),e.outputMin)&&inputParseFloat(server.arg(prefix+"eomax"),e.outputMax)&&parseButton(prefix,e.click)&&inputEncoderSettingValid(e);}
void scheduleRestart(){restartPending=true;restartAt=millis()+NETWORK_RESTART_DELAY_MS;}
